fun liquidation_inner<MarketType, DebtType, CollateralType>(
    id: &mut UID,

    assets: &GenericCoinTypeStorage<Asset<MarketType>>,
    emode_group: &mut EModeGroup,

    reserves: &mut GenericCoinTypeStorage<Reserve<MarketType>>,

    obligation: &mut Obligation<MarketType>,
    liquidation_params: &LiquidationParams,

    mut available_repay_coin: Coin<DebtType>,

    coin_decimals_registry: &CoinDecimalsRegistry,
    x_oracle: &XOracle,
    clock: &Clock,

    now: u64,

    ctx: &mut TxContext,
): (Coin<CollateralType>, Coin<DebtType>, u64) {
    assert!(available_repay_coin.value() != 0, error::liquidation_zero_repay());

    let debt_name = type_name::with_defining_ids<DebtType>();
    let collateral_name = type_name::with_defining_ids<CollateralType>();

    let obligation_old_borrow_amount = obligation.debt(debt_name).unsafe_debt_amount();

    // update all assets interest in the obligation
    refresh_obligation_assets_interest(assets, emode_group, reserves, obligation, now);

    ensure_liquidate_borrow_allowed<MarketType, DebtType>(
        liquidation_params,
        obligation,
        emode_group,
        reserves,
        coin_decimals_registry,
        available_repay_coin.value(),
        x_oracle,
        clock,
    );

    // calculate how much collateral can be seized first
    let obligation_latest_borrow_amount = obligation.debt(debt_name)
        .unsafe_debt_amount()
        // repay a bit more
        .ceil();
    let mut refund_coins = if (obligation_latest_borrow_amount < available_repay_coin.value()) {
        let refund_amount = available_repay_coin.value() - obligation_latest_borrow_amount;
        available_repay_coin.split(refund_amount, ctx)
    } else {
        sui::coin::zero(ctx)
    };

    // NOTE: disable rate limit

    let collateral_reserve = reserves.load_mut_by_type(type_name::with_defining_ids<CollateralType>());
    let exchange_rate = collateral_reserve.exchange_rate<MarketType>(); 

    let mut seized_ctokens = liquidate_calculate_seize_ctokens<DebtType, CollateralType>(
        exchange_rate,
        liquidation_params.liquidation_incentive,
        available_repay_coin.value(),
        emode_group.get_oracle_base_token(),
        x_oracle,
        coin_decimals_registry,
        clock,
    );

    // check if we need to refund debt coin because there might not be enough ctoken to be liquidated
    let total_ctokens = obligation.ctoken_amount_by_coin(type_name::with_defining_ids<CollateralType>());
    if (total_ctokens < seized_ctokens) {
        let expected_repay_amount = float::from_quotient(total_ctokens, seized_ctokens)
            .mul_u64(available_repay_coin.value())
            // repay a bit more
            .ceil();
        let refund = available_repay_coin.value() - expected_repay_amount;

        refund_coins.join(available_repay_coin.split(refund, ctx));
        seized_ctokens = total_ctokens;
    };

    // at this stage, even if there is residual, it should be a very small amount, let the protocol consume the residual
    let _residual = obligation.unsafe_repay_debt_only<MarketType, DebtType>(available_repay_coin.value());

    let ctoken_balance = obligation.withdraw_ctokens<MarketType, CollateralType>(seized_ctokens);
    let ctoken_balance_amount = ctoken_balance.value();
    let refund_balance = collateral_reserve.liquidate_ctokens<MarketType, CollateralType>(
        ctoken_balance.into_coin(ctx),
        liquidation_params.liquidation_revenue_factor,
    );

    let obligation_new_borrow_amount = if (!obligation.has_debt(debt_name)) { float::zero() } else { obligation.debt(debt_name).unsafe_debt_amount() };
    emode_group.update_asset_borrow(debt_name, obligation_old_borrow_amount, obligation_new_borrow_amount);

    let debt_reserve = reserves.load_mut_by_type(debt_name);
    debt_reserve.repay_amount<MarketType, DebtType>(available_repay_coin);

    try_stop_borrow_deleverage<MarketType, DebtType>(id, obligation.emode_group(), emode_group, debt_name);
    try_stop_collateral_deleverage<MarketType, CollateralType>(id, reserves, collateral_name);

module protocol::emode_admin;

use std::type_name::TypeName;
use sui::clock::Clock;
use sui::event::emit;

use protocol::error;
use protocol::app::{AdminCap, ProtocolApp};
use protocol::market::Market;
use protocol::limiter::NewLimiter;
use protocol::emode::{new_emode_params, NewEMode};

const EMODE_CREATED: u8 = 0;
const EMODE_UPDATED: u8 = 1;

const BPS_DENOMINATOR: u64 = 10000;

public struct NewEModeGroupEvent has copy, drop {
    market: TypeName,
    emode_group_id: u8,
    oracle_base_token: u8,
    time: u64,
    operator: address,
}

public struct EModeUpdated<T> has copy, drop {
    who: address,
    what: u8,
    market: TypeName,
    asset: TypeName,
    new: T
}

public fun create_limiter(
    _: &AdminCap,
    self: &ProtocolApp,
    outflow_limit: u64,
    outflow_cycle_duration: u32,
    outflow_segment_duration: u32,
): protocol::limiter::NewLimiter {
    self.ensure_version_matches();

    protocol::limiter::create_new_limiter_change(outflow_limit, outflow_cycle_duration, outflow_segment_duration)
}

public fun onboard_new_emode_group<MarketType>(
    _: &AdminCap,
    self: &ProtocolApp,
    market: &mut Market<MarketType>,
    oracle_base_token: u8,
    clock: &Clock,
    ctx: &mut TxContext,
) {
    assert!(!market.has_circuit_break_triggered(), error::market_under_circuit_break());

    self.validate_market<MarketType>(market);
    self.ensure_version_matches();

    let id = market.emode_registry_mut().new_emode_group(oracle_base_token, ctx);
    let now = clock.timestamp_ms() / 1000;

    emit(NewEModeGroupEvent {
        market: std::type_name::with_defining_ids<MarketType>(),
        emode_group_id: id,
        oracle_base_token,
        time: now,
        operator: ctx.sender(),
    });
}

public fun create_emode_params(
    cap: &AdminCap,
    self: &ProtocolApp,

    collateral_factor_bps: u64,
    liquidation_factor_bps: u64,
    liquidation_incentive_bps: u64,

    max_borrow_amount: u64,
    borrow_weight_bps: u64,

    flash_loan_fee_rate_bps: u64,

    deposit_limiter: NewLimiter,
    borrow_limiter: NewLimiter,
): NewEMode {
    assert!(collateral_factor_bps < liquidation_factor_bps, error::invalid_params_error());
    assert!(liquidation_factor_bps - collateral_factor_bps < liquidation_incentive_bps, error::invalid_params_error());

    self.ensure_version_matches();

    // liquidation factor * (1 + liquidation incentive) < 1
    assert!(
        liquidation_factor_bps * (BPS_DENOMINATOR + liquidation_incentive_bps) / BPS_DENOMINATOR < BPS_DENOMINATOR,
        error::invalid_params_error()
    );

    create_emode_params_inner(
        cap,
        collateral_factor_bps,
        liquidation_factor_bps,
        liquidation_incentive_bps,
        max_borrow_amount,
        borrow_weight_bps,
        flash_loan_fee_rate_bps,
        deposit_limiter,
        borrow_limiter
    )
}

public fun onboard_asset_to_emode_group<MarketType, CoinType>(
    _: &AdminCap,
    self: &ProtocolApp,
    market: &mut Market<MarketType>,
    group: u8,
    params: NewEMode,
    ctx: &mut TxContext,
) {
    assert!(!market.has_circuit_break_triggered(), error::market_under_circuit_break());

    self.validate_market<MarketType>(market);
    self.ensure_version_matches();

    market.emode_registry_mut().support_asset<CoinType>(group, params, ctx);

    emit(EModeUpdated<NewEMode>{
        what: EMODE_CREATED,
        market: std::type_name::with_defining_ids<MarketType>(),
        asset: std::type_name::with_defining_ids<CoinType>(),
        who: ctx.sender(),
        new: params
    });
}

public fun update_asset_in_emode_group<MarketType, CoinType>(
    _: &AdminCap,
    self: &ProtocolApp,
    market: &mut Market<MarketType>,
    group: u8,
    params: NewEMode,
    ctx: &TxContext,
) {
    assert!(!market.has_circuit_break_triggered(), error::market_under_circuit_break());

    self.validate_market<MarketType>(market);
    self.ensure_version_matches();

    let asset = std::type_name::with_defining_ids<CoinType>();
    let emode = market.emode_registry_mut().borrow_mut_emode(group, asset);
    emode.update(params);

    emit(EModeUpdated<NewEMode>{
        what: EMODE_UPDATED,
        market: std::type_name::with_defining_ids<MarketType>(),
        asset,
        who: ctx.sender(),
        new: params
    });
}

fun create_emode_params_inner(
    _: &AdminCap,
    collateral_factor_bps: u64,
    liquidation_factor_bps: u64,
    liquidation_incentive_bps: u64,

    max_borrow_amount: u64,
    borrow_weight_bps: u64,

    flash_loan_fee_rate_bps: u64,

    deposit_limiter: NewLimiter,
    borrow_limiter: NewLimiter,
): NewEMode {
    assert!(collateral_factor_bps < BPS_DENOMINATOR, error::invalid_params_error());
    assert!(liquidation_factor_bps < BPS_DENOMINATOR, error::invalid_params_error());
    assert!(liquidation_incentive_bps < BPS_DENOMINATOR, error::invalid_params_error());
    assert!(borrow_weight_bps >= BPS_DENOMINATOR, error::invalid_params_error());
    assert!(flash_loan_fee_rate_bps < BPS_DENOMINATOR, error::invalid_params_error());

    let collateral_factor = math::float::from_quotient(collateral_factor_bps, BPS_DENOMINATOR);
    let liquidation_factor = math::float::from_quotient(liquidation_factor_bps, BPS_DENOMINATOR);
    let liquidation_incentive = math::float::from_quotient(liquidation_incentive_bps, BPS_DENOMINATOR);
    let borrow_weight = math::float::from_quotient(borrow_weight_bps, BPS_DENOMINATOR);
    let flash_loan_fee_rate = math::float::from_quotient(flash_loan_fee_rate_bps, BPS_DENOMINATOR);

    new_emode_params(
        collateral_factor,
        liquidation_factor,
        liquidation_incentive,
        max_borrow_amount,
        borrow_weight,
        flash_loan_fee_rate,
        deposit_limiter,
        borrow_limiter,
    )
}

#[test_only]
public fun create_emode_params_test(
    cap: &AdminCap,
    collateral_factor_bps: u64,
    liquidation_factor_bps: u64,
    liquidation_incentive_bps: u64,

    max_borrow_amount: u64,
    borrow_weight_bps: u64,

    flash_loan_fee_rate_bps: u64,

    deposit_limiter: NewLimiter,
    borrow_limiter: NewLimiter,
): NewEMode {
    create_emode_params_inner(
        cap,
        collateral_factor_bps,
        liquidation_factor_bps,
        liquidation_incentive_bps,
        max_borrow_amount,
        borrow_weight_bps,
        flash_loan_fee_rate_bps,
        deposit_limiter,
        borrow_limiter
    )
}

